head.script:
scwin.onpageload = function() {
    var row = 100;
    var col = 3;
    var data = [];
    for (var i = 0; i < row; i++) {
        for (var j = 0; j < col; j++) {
            data.push("a_" + (i * col + j) + "B");
        }
    }
    dataList1.setData(data);
};
scwin.onpageunload = function() {};
scwin.gridView1_col1_customModelFormatter = function(value, formattedValue) {
    console.log("col1 customModelFormatter:", arguments);
    return value.toUpperCase();
}
scwin.gridView1_col1_customModelUnformatter = function(value, formattedValue) {
    console.log("col1 customModelUnFormatter:", arguments);
    return value.toLowerCase();
}
scwin.gridView1_col2_customModelFormatter = function(value, formattedValue) {
    console.log("col2 customModelFormatter:", arguments);
    return value.toUpperCase();
}
scwin.gridView1_col2_customModelUnformatter = function(value, formattedValue) {
    console.log("col2 customUnModelFormatter:", arguments);
    return value.toLowerCase();
}
scwin.gridView1_col3_customModelFormatter = function(value, formattedValue) {
    console.log("col3 customModelFormatter:", arguments);
    return value.toUpperCase();
}
scwin.gridView1_col3_customModelUnformatter = function(value, formattedValue) {
    console.log("col3 customModelUnFormatter:", arguments);
    return value.toLowerCase();
}
scwin.input1_customModelFormatter = function(value, formattedValue) {
    return value.toUpperCase();
}
scwin.input1_customModelUnformatter = function(value, formattedValue) {
    return value.toLowerCase();
}
scwin.onpageload2 = function() {
    if (typeof scwin.onpageload === "function") {
        scwin.onpageload();
    }
    if (typeof scwin.unitTest === "function") {
        scwin.unitTest();
    }
}
